From 837dae0aed8ad4cbfeafe53c474b7e2ed579554e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 17:01:43 +0100
Subject: [PATCH] applets/taskmanager: reorder grouped windows by dragging
 their previews

There was no way to change the order of a group's windows in its tooltip,
which is also the order clicking the task cycles through. With manual
sorting, dragging a window preview (or its title) now moves that window.

BUG: 508968
---
 applets/taskmanager/qml/ToolTipInstance.qml | 32 +++++++++++++++++++++
 1 file changed, 32 insertions(+)

diff --git a/applets/taskmanager/qml/ToolTipInstance.qml b/applets/taskmanager/qml/ToolTipInstance.qml
index 5a42d24a17..d139f9a41a 100644
--- a/applets/taskmanager/qml/ToolTipInstance.qml
+++ b/applets/taskmanager/qml/ToolTipInstance.qml
@@ -20,6 +20,7 @@ import org.kde.plasma.components as PlasmaComponents3
 import org.kde.plasma.extras as PlasmaExtras
 import org.kde.kirigami as Kirigami
 import org.kde.kwindowsystem
+import org.kde.taskmanager as TaskManager

 ColumnLayout {
     id: root
@@ -260,6 +261,29 @@ ColumnLayout {
             }
         }

+        // Reorders the windows of a group by dragging their entries
+        component ToolTipDragHandler: DragHandler {
+            readonly property ListView view: root.ListView.view
+            readonly property bool canReorder: view !== null && tasksModel.sortMode === TaskManager.TasksModel.SortManual
+
+            target: null
+
+            onActiveChanged: {
+                // Keep the list from taking the drag over as a flick
+                view.interactive = !active;
+            }
+            onCentroidChanged: {
+                if (!active) {
+                    return;
+                }
+                const pos = parent.mapToItem(view.contentItem, centroid.position);
+                const above = view.itemAt(pos.x, pos.y) as ToolTipInstance;
+                if (above && above.index !== root.index) {
+                    tasksModel.move(root.index, above.index, root.submodelIndex.parent);
+                }
+            }
+        }
+
         ToolTipHoverHandler {
             id: headerHoverHandler
             enabled: (root.index !== -1) && !Plasmoid.configuration.showToolTips && thumbnailSourceItem.winId != undefined
@@ -270,6 +294,10 @@ ColumnLayout {
             enabled: (root.index !== -1) && !Plasmoid.configuration.showToolTips && thumbnailSourceItem.winId != undefined
         }

+        ToolTipDragHandler {
+            enabled: headerTapHandler.enabled && canReorder
+        }
+
         // There's no PlasmaComponents3 version
         PlasmaExtras.Highlight {
             id: headerHoverHighlight
@@ -395,6 +423,10 @@ ColumnLayout {
             id: tapHandler
             enabled: root.index !== -1 && Plasmoid.configuration.showToolTips && thumbnailSourceItem.winId != undefined
         }
+
+        ToolTipDragHandler {
+            enabled: tapHandler.enabled && canReorder
+        }
     }

     // Player controls row, load on demand so group tooltips could be loaded faster
-- 
